/* =====================================================================
   PART 7 — TOXICOLOGY & ANTIDOTES
   Indian-context emergencies: organophosphate/carbamate, snake bite,
   scorpion sting, aluminium phosphide, illicit-liquor (methanol),
   rodenticide (superwarfarin), paracetamol, sedative-hypnotics,
   TCA/salicylate, LAST, methaemoglobinaemia, cyanide, alcohols
   ===================================================================== */

/* ---------- gastrointestinal decontamination ---------- */
R({ id:'activated-charcoal', n:'Activated charcoal', sys:'tox', cls:'Adsorbent — high surface-area carbon',
  ind:'Ingestion of an adsorbable toxin within 1 h (paracetamol, salicylate, carbamazepine, phenobarbitone, dapsone, quinine, colchicine, theophylline, digoxin, TCA, β-blockers)', pop:'all', risk:3,
  d:{t:'gkg', lo:0.5, hi:1, cap:50, rep:'single dose 1 g/kg (max 50 g adult / 25 g child); multi-dose only for carbamazepine, dapsone, phenobarbitone, quinine, theophylline'},
  fx:[{s:'50 g/240 mL suspension (20.8%)', c:0.208, u:'g', p:'240 mL bottle (50 g) ready-to-use', b:'Activated Charcoal (E Merck), Charcodote, Actidose-Aqua, Carbomix — availability in Indian pharmacies is variable; many centres keep the powder and reconstitute', r:'PO', hl:1},
      {s:'Charcoal powder', c:1, u:'g', p:'30 g / 50 g sachet — mix with water to a slurry (8 g in 100 mL)', b:'Activated charcoal powder (Merck/Loba)', r:'PO', prep:'Mix 50 g of powder with 250–300 mL of water to form a slurry; shake well before and during administration'}],
  admin:'1 g/kg PO/NG (max 50 g in adults, 25 g in children) as a slurry within 1 hour of ingestion. Multi-dose activated charcoal (0.5 g/kg every 2–4 h) only for carbamazepine, dapsone, phenobarbitone, quinine and theophylline. Ensure the airway is protected or the patient is fully alert.',
  dil:'Mix to a slurry; do not give dry powder (risk of aspiration and impaction). May be given with a cathartic ONCE (not repeatedly).',
  warn:['ASPIRATION PNEUMONITIS — contraindicated in an unprotected airway, reduced conscious level without an ETT, ileus, bowel obstruction, or after corrosive ingestion.','Does NOT adsorb: alcohols, methanol, ethylene glycol, lithium, iron, cyanide, potassium, acids/alkalis, hydrocarbons, heavy metals.','It adsorbs N-acetylcysteine and many oral antidotes — separate administration by at least 1–2 h.','Vomiting occurs in ~20%; corneal abrasion if splashed.','Routine use is NOT recommended for all ingestions — restrict to the specific indications above within 1 h.'],
  ref:['AACT-CHARCOAL','EAPCCT','GOLDFRANK','TINTINALLI','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

/* ---------- paracetamol ---------- */
R({ id:'nac-paracetamol', n:'N-acetylcysteine (NAC)', sys:'tox', cls:'Glutathione precursor / sulfhydryl donor',
  ind:'PARACETAMOL (ACETAMINOPHEN) OVERDOSE — the definitive antidote; also used for non-paracetamol acute liver failure, contrast nephropathy prophylaxis (historical) and as a mucolytic', pop:'all', risk:4,
  d:{t:'mgkg', lo:100, hi:150, capDay:300, rep:'21-h regimen: 150 mg/kg over 1 h → 50 mg/kg over 4 h → 100 mg/kg over 16 h (total 300 mg/kg/21 h)'},
  fx:[{s:'200 mg/mL (20%)', c:200, u:'mg', p:'2 g/10 mL vial, 4 mL ampoule (800 mg)', b:'Mucomix (Abbott/Sun), NAC (Samarth), Mucolite injectable, N-Acetylcysteine IP — Neon/Intas; Mucomyst (import)', r:'IV/PO/NEB', hl:1},
      {s:'100 mg/mL (10%)', c:100, u:'mg', p:'4 mL ampoule (400 mg), 10 mL vial (1 g)', b:'Mucomix 10%, NAC 10%', r:'PO/NEB/IV'},
      {s:'600 mg effervescent tablet / sachet (oral)', c:600, u:'mg', p:'sachet/strip', b:'Mucolite 600, NAC 600, Mucomix oral', r:'PO'}],
  admin:'STANDARD 21-HOUR IV REGIMEN: (1) 150 mg/kg in 200 mL of 5% dextrose over 15–60 min (children <20 kg: 3 mL/kg of diluent). (2) 50 mg/kg in 500 mL of 5% dextrose over 4 h. (3) 100 mg/kg in 1000 mL of 5% dextrose over 16 h. Continue the 100 mg/kg/16 h infusion (or extend at 6.25 mg/kg/h) until the INR <1.3, ALT is falling, the patient is encephalopathy-free and paracetamol is undetectable.',
  dil:'ALWAYS dilute in 5% dextrose (or NS). Final concentration ≤30 mg/mL for peripheral infusion. In children <20 kg use 3 mL/kg of diluent for the first stage.',
  warn:['ANAPHYLACTOID REACTIONS (flushing, urticaria, bronchospasm, hypotension) occur in 10–20%, almost always during the FIRST (150 mg/kg) infusion and are related to the rate. Management: STOP the infusion, give an antihistamine ± salbutamol ± adrenaline, then RESTART at a slower rate once symptoms resolve. It is NOT a true allergy and is NOT a reason to abandon NAC.','START WITHIN 8 H OF INGESTION FOR FULL PROTECTION. Between 8 and 24 h still give a full course. Beyond 24 h, or for staggered/unknown-time ingestion with a raised ALT or detectable paracetamol, give NAC until the criteria above are met.','Use the Rumack–Matthew nomogram (treatment line 150 mg/kg / 1000 µmol/L at 4 h in India; the UK now treats everyone above 100 mg/L). Levels drawn before 4 h are uninterpretable — repeat at 4 h.','Check INR, ALT, AST, creatinine, glucose, ABG and phosphate at baseline, 12 h and 24 h. King\'s College Criteria for transplant referral: pH <7.3 after resuscitation, OR all three of INR >6.5, creatinine >300 µmol/L and grade III–IV encephalopathy.','Oral NAC (140 mg/kg load then 70 mg/kg q4h × 17 doses) is an alternative but causes vomiting in ~30%; give with metoclopramide or via NG tube.','NAC has an unpleasant sulphurous smell — warn the patient.','The 2-bag "SNAP" regimen (100 mg/kg over 2 h then 200 mg/kg over 10 h) reduces anaphylactoid reactions and is now used in many centres.'],
  ref:['MHRA-NAC','AACT-NAC','UK-PARACETAMOL','GOLDFRANK','IAP-TOX','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

/* ---------- organophosphate / carbamate ---------- */
R({ id:'atropine-op', n:'Atropine — organophosphate & carbamate poisoning', sys:'tox', cls:'Competitive muscarinic antagonist',
  ind:'Cholinergic crisis from organophosphorus or carbamate insecticide poisoning (monocrotophos, chlorpyrifos, quinalphos, malathion, parathion; carbaryl, aldicarb) — THE MOST COMMON FATAL POISONING IN RURAL INDIA', pop:'all', risk:5, inf:true,
  d:{t:'mgkg', lo:0.05, hi:0.05, capDay:500, rep:'2 mg IV (adult) or 0.05 mg/kg IV (child, min 0.1 mg) EVERY 5 MIN until fully atropinised — the dose is DOUBLED every 5 min if there is no response, so there is NO single-dose ceiling; cumulative doses of 20–500 mg over 24 h are common'},
  diln:[{l:'40 mg in 40 mL NS → 1 mg/mL (infusion syringe)', amt:40, in:40, u:'mg', bag:'40 mL 0.9% NaCl'},
        {l:'20 mg in 500 mL NS → 40 mcg/mL (gravity drip)', amt:20, in:500, u:'mg', bag:'500 mL 0.9% NaCl'}],
  fx:[{s:'0.6 mg/mL', c:0.6, u:'mg', p:'1 mL ampoule — LARGE QUANTITIES ARE NEEDED: stock 100+ ampoules', b:'Atropine Sulphate IP — Neon, Samarth, Saraca, Vins', r:'IV/IM/SC/ETT', hl:1},
      {s:'1 mg/mL', c:1, u:'mg', p:'1 mL / 10 mL ampoule', b:'Atropine 1 mg/mL (some brands)', r:'IV'}],
  admin:'Give 2 mg IV (adult; 0.05 mg/kg child, minimum 0.1 mg) EVERY 5 MINUTES — DO NOT WAIT for a response before the next dose. Double the dose every 5 min if there is no response. Continue until ATROPINISATION: (1) dry axillae and skin, (2) heart rate >80/min, (3) systolic BP >80 mmHg, (4) clear chest on auscultation (bronchorrhoea resolved), (5) dilated pupils. Pupils and heart rate alone are UNRELIABLE endpoints. Maintenance: continuous IV infusion of 10–20% of the total atropinising dose PER HOUR, titrated to dry secretions; do not stop abruptly — taper over 24–48 h.',
  dil:'Dilute for infusion in NS; may also be given via an ETT in 0.1 mg/mL dilution if no IV access.',
  warn:['THE ENDPOINT IS DRY LUNGS AND DRY SKIN, NOT A TARGET HEART RATE OR PUPIL SIZE — under-dosing (secretions persist) and over-dosing (atropine delirium, hyperthermia, ileus, urinary retention) are both common causes of death.','Never stop atropine abruptly — rebound cholinergic crisis can be fatal. Wean over 24–48 h.','AVOID: morphine (respiratory depression), aminophylline/theophylline (arrhythmias), phenothiazines, and SUXAMETHONIUM (prolonged apnoea from plasma cholinesterase inhibition — use a non-depolariser if paralysis is needed).','Decontaminate: remove all clothing, wash skin and hair with soap and water (staff must wear gloves/apron — secondary contamination of healthcare workers is well documented), consider gastric lavage within 1 h of ingestion.','Prone positioning/aspiration risk from bronchorrhoea — early intubation is often needed; anticipate "intermediate syndrome" (neck flexor, cranial nerve and respiratory muscle weakness) 24–96 h after exposure, which requires prolonged ventilation.','Measure plasma (butyryl) cholinesterase — a level <50% of normal supports the diagnosis but does NOT guide therapy; do not delay atropine waiting for it.','Give pralidoxime for organophosphate (not carbamate) poisoning within 24 h where possible.'],
  ref:['WHO-OP','IAP-TOX','AIIMS-OP','GOLDFRANK','TINTINALLI','ICMR-PESTICIDE','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'pralidoxime', n:'Pralidoxime (2-PAM)', sys:'tox', cls:'Cholinesterase reactivator (oxime)',
  ind:'Organophosphorus insecticide poisoning — reactivates phosphorylated acetylcholinesterase if given before "ageing" (adjunct to atropine, never a substitute)', pop:'all', risk:4, inf:true,
  d:{t:'mgkg', lo:25, hi:50, cap:2000, rep:'loading 30 mg/kg IV over 15–30 min (max 2 g), then 8 mg/kg/h infusion for 24–48 h'},
  diln:[{l:'2 g in 500 mL NS → 4 mg/mL (infusion)', amt:2, in:500, u:'g', bag:'500 mL 0.9% NaCl'},
        {l:'1 g in 100 mL NS → 10 mg/mL', amt:1, in:100, u:'g', bag:'100 mL 0.9% NaCl'}],
  fx:[{s:'200 mg/mL (1 g/5 mL ampoule)', c:200, u:'mg', p:'5 mL ampoule (1 g)', b:'Pralidoxime Chloride IP — Samarth, Neon; PAM, Obidoxime alternatives; availability in India is LIMITED and should be pre-arranged at district level', r:'IV/IM', hl:1, prep:'Dilute 1 g in 100 mL NS and infuse over 15–30 min'},
      {s:'1 g lyophilised vial', c:1, u:'mg', p:'1 g vial reconstituted with 20 mL WFI → 50 mg/mL', b:'Pralidoxime chloride 1 g vial (import/National stockpile)', r:'IV/IM', prep:'Reconstitute 1 g with 20 mL sterile WFI → 50 mg/mL'}],
  admin:'Loading 30 mg/kg IV over 15–30 min (max 2 g) within 24 h of exposure (ideal <6–12 h), then a continuous infusion of 8 mg/kg/h (or intermittent 1 g every 4 h) for 24–48 h, or until 24 h after the patient is off atropine and symptom-free. Alternative WHO regimen: 1–2 g load then 0.5 g/h.',
  dil:'Dilute in NS or D5W; infuse slowly (rapid injection causes neuromuscular blockade, tachycardia, laryngospasm and rigidity).',
  warn:['INEFFECTIVE for CARBAMATE poisoning (carbamate-cholinesterase binding is reversible and short-lived) — atropine alone is the treatment.','Must be given EARLY: after "ageing" of the enzyme (minutes for soman/dimethyl compounds, hours to days for diethyl compounds such as chlorpyrifos), oximes cannot reactivate it.','Evidence is conflicting (some trials showed harm with high-dose regimens) — use the 30 mg/kg load + 8 mg/kg/h regimen and never exceed it.','Rapid injection → hypertension, tachycardia, laryngospasm, neuromuscular blockade.','Availability in Indian district hospitals is erratic — maintain a regional stockpile and verify supply.','Pralidoxime does NOT replace atropine; both must be given.'],
  ref:['WHO-OP','AIIMS-OP','IAP-TOX','GOLDFRANK','ICMR-PESTICIDE','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

/* ---------- envenomation ---------- */
R({ id:'asv-snakebite', n:'Anti-Snake Venom Serum (polyvalent ASV)', sys:'tox', cls:'Equine immunoglobulin F(ab′)₂ — passive antivenom',
  ind:'Systemic envenomation by the "Big Four" Indian snakes: Russell\'s viper, common krait, Indian cobra, saw-scaled viper — indicated by incoagulable blood (20WBCT >20 min), spontaneous bleeding, neurotoxicity (ptosis), or rapidly extending local swelling', pop:'all', risk:5,
  d:{t:'units', lo:10, hi:10, rep:'INITIAL DOSE 10 VIALS IV — the SAME dose for adults, children, pregnant women and the elderly (venom load is not weight-dependent)'},
  fx:[{s:'10 mL lyophilised vial (each vial neutralises 10 mg Russell\'s viper, 10 mg common krait, 10 mg Indian cobra and 0.45 mg saw-scaled viper venom)', c:1, u:'units', p:'10 mL vial — reconstitute EACH vial with 10 mL sterile water/WFI', b:'Polyvalent ASV (equine) — Serum Institute of India, Bharat Serums (Hynosis-class), Vins, Haffkine, PSVPL, Central Research Institute Kasauli; ASV, Polyvalent Anti-Snake Venom Serum', r:'IV', hl:1, prep:'Reconstitute each of the 10 vials with 10 mL of sterile water for injection (total 100 mL), swirl gently (avoid foaming), then add to 400 mL of 0.9% NaCl (or use the 100 mL directly with a syringe pump in a fluid-restricted child) and infuse over 30–60 min'}],
  admin:'(1) Confirm the indication: 20-minute whole-blood clotting test (20WBCT) incoagulable, spontaneous systemic bleeding, ptosis/ophthalmoplegia/respiratory paralysis, or local swelling involving >50% of the limb, crossing a joint, or extending rapidly. (2) Give 10 vials reconstituted and diluted as above; start slowly (first 10 mL over 10–15 min) with the physician at the bedside, then increase to complete the dose over 30–60 min. (3) Observe every 5 min for the first 30 min, then every 15 min for 2 h for an early reaction. (4) REPEAT DOSING — neurotoxic envenomation (krait/cobra): if no improvement at 1 h, repeat 10 vials (maximum 20 vials); haemotoxic (viper): repeat at 6 h if the 20WBCT is still incoagulable (maximum 30 vials). (5) Give the anticholinesterase test for neurotoxic bites: atropine 0.6 mg IV (child 20 mcg/kg) then neostigmine 0.02–0.04 mg/kg IV (max 1 mg) — continue 6-hourly if there is a response. (6) Analgesia with paracetamol only. (7) Tetanus prophylaxis. (8) Monitor 20WBCT 6-hourly, platelets, fibrinogen, creatinine, urine output and Hb.',
  dil:'Reconstitute each vial with 10 mL sterile water; dilute in 0.9% NaCl. Use within 4 h of reconstitution.',
  warn:['ANAPHYLAXIS AND EARLY ADVERSE REACTIONS occur in 20–40% (higher with some batches). Have ADRENALINE 1:1000 DRAWN UP AND READY (two syringes) BEFORE starting the infusion, plus hydrocortisone, an antihistamine, IV fluids and airway equipment. Prophylactic low-dose adrenaline 0.25 mg SC (child 5 mcg/kg) is recommended by some Indian protocols — check your local guideline.','At the earliest sign of a reaction: STOP the infusion temporarily, treat with IM adrenaline 0.5 mg (child 0.01 mg/kg), hydrocortisone 200 mg IV and chlorpheniramine 10 mg IV, then restart at a slower rate once controlled.','NEVER give ASV by the IM route and NEVER inject it locally at the bite site.','No ASV is effective for sea snakes, green pit vipers or hump-nosed vipers (Hypnale) — do not give it for these bites.','Do not delay: no skin sensitivity test is required (it does not predict reactions and wastes time).','Serum sickness (fever, rash, arthralgia, proteinuria) in 5–20% at 5–14 days — treat with a short course of prednisolone and an antihistamine.','Snakebite is a notified disease in India; the 2024 National Clinical Protocol for the Management of Snakebite should be followed.','20WBCT technique: collect 2 mL of venous blood into a CLEAN, DRY, GLASS tube (never heparinised or plastic), leave undisturbed for exactly 20 min at room temperature, then tip once — unclotted blood = incoagulable = repeat ASV.'],
  ref:['NATL-SNAKEBITE-2024','WHO-SNAKEBITE','NHM-SNAKEBITE','IAP-TOX','ISCCM-ENVENOM','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'neostigmine-snake', n:'Neostigmine + atropine — neurotoxic snake bite', sys:'tox', cls:'Acetylcholinesterase inhibitor (anticholinesterase test)',
  ind:'Post-synaptic neurotoxic envenomation (Indian cobra) with ptosis/bulbar palsy — krait venom is PRE-synaptic and does not respond', pop:'all', risk:4,
  d:{t:'mgkg', lo:0.02, hi:0.04, cap:5, capDay:10, rep:'neostigmine 0.02–0.04 mg/kg IV (child max 1 mg per dose; adult usual 0.5–2 mg, max 5 mg per dose, max 10 mg/24 h) with atropine 0.6 mg IV (child 20 mcg/kg) — repeat 4–6-hourly if the ptosis improves'},
  fx:[{s:'0.5 mg/mL neostigmine', c:0.5, u:'mg', p:'1 mL ampoule (0.5 mg), 5 mL vial (2.5 mg)', b:'Neostigmine IP — Abbott, Samarth, Neon; Neoton, Prostigmin', r:'IV/IM', hl:1},
      {s:'0.6 mg/mL atropine', c:0.6, u:'mg', p:'1 mL ampoule', b:'Atropine Sulphate IP — Neon, Samarth', r:'IV'}],
  admin:'Give atropine 0.6 mg IV (child 20 mcg/kg, max 0.6 mg) FIRST to prevent muscarinic side effects, then neostigmine 0.02–0.04 mg/kg IV (adult usual 0.5–2 mg, max 5 mg). Assess the ptosis and motor power 30–60 min later; if there is objective improvement, continue neostigmine every 4–6 h (max 10 mg/24 h) together with ASV.',
  dil:'Ready to use; may be diluted in NS.',
  warn:['ALWAYS give atropine before or with neostigmine — otherwise bradycardia, bronchospasm, salivation and abdominal cramps occur.','Krait (Bungarus) venom causes PRE-synaptic neurotoxicity that does NOT respond to anticholinesterases — supportive ventilation is the mainstay.','Continue ventilatory support regardless of the response — respiratory failure may progress over 24–72 h.','Neostigmine is only an adjunct; ASV and mechanical ventilation are the definitive treatments.'],
  ref:['NATL-SNAKEBITE-2024','WHO-SNAKEBITE','NHM-SNAKEBITE','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'prazosin-scorpion', n:'Prazosin — Indian red scorpion (Mesobuthus tamulus) sting', sys:'tox', cls:'Selective α1-adrenergic antagonist',
  ind:'Scorpion sting with systemic envenomation (autonomic storm, hypertension, tachycardia, pulmonary oedema, myocardial dysfunction) — the single most important intervention; reduced mortality from ~30% to <4%', pop:'all', risk:4,
  d:{t:'mcgkg', v:30, cap:500, capDay:5000, rep:'30 mcg/kg PO/NG (adult 0.5 mg) every 3 h until the extremities are warm and dry with visible peripheral veins, then every 6–12 h for 48 h'},
  fx:[{s:'1 mg scored tablet', c:1, u:'mg', p:'strip of 10', b:'Minipress (Pfizer), Prazopress, Prazosin IP — Cipla/Sun/Intas; the 1 mg scored tablet is the practical paediatric form', r:'PO', hl:1},
      {s:'2.5 mg / 5 mg tablets', c:2.5, u:'mg', p:'strip of 10', b:'Minipress 2.5/5 mg', r:'PO', own:{text:'Prazosin 2.5 mg and 5 mg tablets exist in India but are NOT used for scorpion envenomation — the 1 mg SCORED tablet is the formulation used (30 mcg/kg in children, 0.5 mg in adults). Listed for completeness of availability.'}},
      {s:'Anti-scorpion venom serum (ASVS) 100 mg vial', c:100, u:'mg', p:'lyophilised vial reconstituted with 10 mL', b:'Hynosis-ASV (Bharat Serums) — available but rarely stocked; efficacy data are limited', r:'IV', own:{text:'Anti-scorpion venom serum (Hynosis, anti-Hottentotta tamulus) — available in India but rarely used and of unproven benefit. PRAZOSIN remains the first-line drug and should be given irrespective of the blood pressure.'}}],
  admin:'(1) Give prazosin 30 mcg/kg PO or via NG (adult 0.5 mg; a child weighing 8 kg needs 0.25 mg = a quarter of a 1 mg scored tablet) as SOON AS systemic envenomation is recognised, irrespective of the blood pressure. (2) Repeat every 3 h until the extremities are warm, dry and the peripheral veins are visible, then every 6–12 h for 48 h. (3) For pulmonary oedema or LV dysfunction, ADD dobutamine 5–15 mcg/kg/min. (4) Monitor BP, heart rate and respiratory rate every 30 min for 3 h, then hourly for 6 h, then 4-hourly.',
  dil:'Crush the tablet and give via an NG tube if the patient is vomiting.',
  warn:['FIRST-DOSE PHENOMENON (postural hypotension and syncope) — keep the patient LYING FLAT for 3 h after each dose, and avoid sitting them up for examination during this period.','Do not give atropine, morphine, sedatives, β-blockers or calcium channel blockers — they worsen the outcome.','Prazosin should NOT be given if pain at the sting site is the only symptom (Grade I envenomation).','Avoid dopamine and bolus fluids for scorpion pulmonary oedema — dobutamine plus prazosin is the correct combination.','Doses up to 80–90 mcg/kg within 1–2 h have been reported safe in severe paediatric envenomation.','Local measures (tourniquets, incision, suction, ice) are harmful and must not be used.','Tetanus prophylaxis and analgesia with paracetamol are indicated.'],
  ref:['BAWASKAR-PRAZOSIN','IAP-TOX','ISCCM-ENVENOM','NATL-SNAKEBITE-2024','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

/* ---------- sedative-hypnotic & psychotropic ---------- */
R({ id:'tca-bicarb', n:'Sodium bicarbonate — tricyclic antidepressant (TCA) overdose', sys:'tox', cls:'Alkalinising agent / sodium load',
  ind:'TCA (amitriptyline, imipramine, nortriptyline, dosulepin) overdose with QRS >100 ms, ventricular arrhythmia, hypotension or acidosis — VERY COMMON INDIAN SELF-POISONING', pop:'all', risk:5,
  d:{t:'meqkg', lo:1, hi:2, cap:200, rep:'1–2 mEq/kg IV bolus over 1–2 min, then an infusion of 150 mEq/L at 1.5–3 mL/kg/h to keep pH 7.45–7.55'},
  fx:[{s:'8.4% (1 mEq/mL)', c:1, u:'mEq', p:'20 mL / 50 mL vial', b:'Sodabic, Sodium Bicarbonate IP — Samarth, Neon', r:'IV', hl:1},
      {s:'7.5% (0.893 mEq/mL)', c:0.893, u:'mEq', p:'15 mL ampoule', b:'Sodium Bicarbonate 7.5% — Neon', r:'IV'},
      {s:'5% dextrose or NS for the maintenance infusion', c:1, u:'ml', p:'1000 mL bag', b:'Dextrose 5%, Normal Saline IP', r:'IV', use:'fixed', give:'Dilute 3 x 50 mL ampoules of 8.4% NaHCO3 in 1000 mL of 5% dextrose or water for injection to give an approximately isotonic 150 mmol/L solution; run at 100-200 mL/h to keep the serum pH 7.45-7.55.'}],
  admin:'1–2 mEq/kg IV over 1–2 min, repeated every 3–5 min until the QRS narrows (<100 ms), the arrhythmia stops or the pH reaches 7.45–7.55. Then maintain with an infusion of 150 mEq of 8.4% bicarbonate in 1 L of D5W at 1.5–3 mL/kg/h.',
  dil:'For the maintenance infusion add 150 mL of 8.4% bicarbonate to 850 mL of D5W (or 3 ampoules of 50 mL to a 1 L bag).',
  warn:['Target pH 7.45–7.55 — do NOT exceed 7.60 (alkalosis causes hypokalaemia, seizures, arrhythmias and a left-shifted oxyhaemoglobin curve).','Correct hypokalaemia aggressively (alkalosis drives K⁺ intracellularly and worsens arrhythmias).','AVOID: physostigmine (asystole in TCA overdose), class Ia/Ic/III antiarrhythmics (quinidine, procainamide, flecainide, amiodarone, sotalol — all worsen conduction), and propranolol.','Hyperventilation is a useful temporary measure while bicarbonate is obtained.','Lipid emulsion 20% for refractory cardiovascular collapse.','Sodium load causes hypernatraemia, hypokalaemia and pulmonary oedema — monitor.','ECG criteria for risk: QRS >100 ms (seizures), QRS >160 ms (ventricular arrhythmias), terminal R wave in aVR >3 mm.','Do not give ipecac or induce vomiting; activated charcoal within 1–2 h is useful (TCAs slow gastric emptying).'],
  ref:['GOLDFRANK','TINTINALLI','EXPERT-TCA','BNF','AHA-TOX','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'alcohol-withdrawal', n:'Alcohol withdrawal — benzodiazepine protocol', sys:'tox', cls:'Long/intermediate-acting benzodiazepine + thiamine',
  ind:'Alcohol withdrawal syndrome, alcoholic hallucinosis, withdrawal seizures and delirium tremens — extremely common in Indian ICUs', pop:'adult', risk:4,
  d:{t:'mg', lo:10, hi:20, capDay:400, rep:'symptom-triggered: diazepam 10 mg PO/IV every 1 h until the CIWA-Ar score <8 and the patient is calm but rousable (loading-dose method), then PRN'},
  fx:[{s:'5 mg/mL diazepam', c:5, u:'mg', p:'2 mL ampoule (10 mg)', b:'Diazepam IP — Samarth, Neon; Valium (Roche), Calmpose', r:'IV/PO/PR', hl:1},
      {s:'10 mg diazepam tablet', c:10, u:'mg', p:'strip of 10', b:'Valium 10, Calmpose 10', r:'PO'},
      {s:'25 mg chlordiazepoxide capsule', c:25, u:'mg', p:'strip of 10 (also 10 mg)', b:'Librium (Abbott), Chlordiazepoxide IP, Equbeta, Posesca', r:'PO', own:{lo:50,hi:100,u:'mg',l:'CHLORDIAZEPOXIDE 50–100 mg PO 6-hourly — the oral option for milder withdrawal.'}},
      {s:'2 mg/mL lorazepam injection', c:2, u:'mg', p:'1 mL ampoule — availability limited in India', b:'Lorazepam IP (Intas/Neon), Ativan (import)', r:'IV/PO', own:{a:2,u:'mg',l:'LORAZEPAM 2 mg IV/PO hourly — preferred in liver disease and the elderly (no active metabolites, no hepatic oxidation).'}},
      {s:'1 mg lorazepam tablet', c:1, u:'mg', p:'strip of 10', b:'Lorivan (Abbott India)', r:'PO/SL', own:{a:2,u:'mg',l:'LORAZEPAM 2 mg PO/SL hourly (two 1 mg tablets).'}},
      {s:'100 mg/mL thiamine', c:100, u:'mg', p:'1 mL ampoule', b:'Thiamine IP — Neon, Samarth', r:'IV/IM', own:{lo:100,hi:500,u:'mg',l:'THIAMINE 100–500 mg IV — MUST be given BEFORE any dextrose (Wernicke encephalopathy prophylaxis). Dextrose first can precipitate Wernicke.'}}],
  admin:'SYMPTOM-TRIGGERED (CIWA-Ar): score every 1–2 h; if ≥10 give diazepam 10 mg PO/IV (or lorazepam 2 mg PO/IV in liver disease/elderly), repeat hourly until the score is <8 and the patient is calm but easily rousable. LOADING-DOSE METHOD: diazepam 10 mg PO/IV every hour until sedated (typical total 40–100 mg). Chlordiazepoxide 50–100 mg PO 6-hourly is the oral alternative for milder withdrawal. Delirium tremens: IV benzodiazepine infusion ± phenobarbitone 260 mg IV every 15–20 min to effect ± dexmedetomidine/propofol; intubate and ventilate as required. ALWAYS give thiamine 100–500 mg IV before any dextrose.',
  dil:'Diazepam should be given undiluted IV slowly into a large vein (precipitates on dilution); do not mix with other drugs.',
  warn:['USE LORAZEPAM OR OXAZEPAM IN ADVANCED LIVER DISEASE, THE ELDERLY, OR SHOCK — diazepam and chlordiazepoxide have active long-acting metabolites that accumulate in hepatic impairment.','Thiamine BEFORE glucose: dextrose loading in thiamine deficiency precipitates Wernicke encephalopathy.','Check and correct magnesium, potassium, phosphate, calcium, glucose and sodium — withdrawal seizures are often related to hypomagnesaemia.','Avoid phenytoin for alcohol-withdrawal seizures (ineffective); benzodiazepines are the treatment.','Delirium tremens carries 5–15% mortality — treat in a monitored setting.','Consider phenobarbitone for benzodiazepine-refractory DTs; it acts at a different GABA-A site and reduces the need for intubation.','Haloperidol may be added for severe hallucinations AFTER adequate benzodiazepine loading, but it lowers the seizure threshold — never use it alone.','Screen for head injury, sepsis, GI bleeding, pancreatitis and Wernicke encephalopathy as causes of altered mental status.'],
  ref:['ASAM-WD','BNF','ISCCM-TOX','TINTINALLI','RCPSY-AW'] });

/* ---------- toxic alcohols ---------- */
R({ id:'fomepizole-ethanol', n:'Fomepizole or ethanol — methanol / ethylene glycol poisoning', sys:'tox', cls:'Alcohol dehydrogenase (ADH) competitive inhibitor',
  ind:'Illicit liquor ("hooch") methanol poisoning — recurrent outbreaks in India; ethylene glycol (antifreeze) ingestion; unexplained high-anion-gap metabolic acidosis with an osmolar gap >10', pop:'all', risk:5, inf:true,
  d:{t:'mgkg', lo:10, hi:15, capDay:2000, rep:'fomepizole 15 mg/kg IV load, then 10 mg/kg every 12 h × 4 doses, then 15 mg/kg q12h until the methanol/ethylene glycol level <20 mg/dL and the acidosis has resolved'},
  diln:[{l:'10% ethanol in 5% dextrose: load 7.5 mL/kg then 1.5–2 mL/kg/h (0.1–0.15 g/kg/h)', amt:100, in:1000, u:'g', bag:'1000 mL of 5% dextrose with 100 g of absolute ethanol (pharmacy-compounded)'},
        {l:'20% ethanol in D5W (for fluid restriction)', amt:200, in:1000, u:'g', bag:'compounded by pharmacy'}],
  fx:[{s:'Fomepizole 1.5 g/1.5 mL vial (1 g/mL)', c:1000, u:'mg', p:'1.5 mL vial — VERY LIMITED availability in India (import/named-patient)', b:'Antizol (Cumberland) — import; Indian generics are not marketed', r:'IV', hl:1, prep:'Dilute 15 mg/kg in 100 mL NS and infuse over 30 min'},
      {s:'Absolute ethanol (pharmacy-compounded 10% in D5W = 0.1 g/mL)', c:0.1, u:'g', p:'compounded 10% w/v in D5W — the standard Indian alternative', b:'Compounded in-house by the pharmacy from USP absolute alcohol; commercial ethanol injections are not available in India', r:'IV', own:{kgLo:0.6,kgHi:0.8,u:'g',l:'ETHANOL LOAD 0.6–0.8 g/kg IV over 30–60 min (= 6–8 mL/kg of 10% ethanol), then maintain 0.1–0.15 g/kg/h (1–1.5 mL/kg/h; DOUBLE the rate in chronic alcoholics). Target a serum ethanol of 100–150 mg/dL.'}},
      {s:'Oral ethanol 40% spirit (last resort)', c:0.4, u:'g', p:'measured oral/NG dose', b:'Rectified spirit — only if no other option; use a measured pharmaceutical preparation', r:'PO', own:{kg:0.8,u:'g',l:'ORAL ethanol LOAD 0.8 g/kg of 40% spirit, then 0.15 g/kg/h — only if IV ethanol is impossible. It is the usual option in India.'}},
      {s:'Folinic acid / folic acid', c:1, u:'mg', p:'15 mg/1.5 mL ampoule (folinic); 1 mg/mL folic acid', b:'Foligraf (Bharat Parentals), Leucovorin; Folvite 1 mg/5 mg tablets', r:'IV/PO', own:{kgLo:1,kgHi:2,u:'mg',cap:50,l:'FOLINIC ACID 1–2 mg/kg IV q4–6h (max 50 mg/dose) for METHANOL poisoning (it accelerates formate metabolism). For ETHYLENE GLYCOL give thiamine 100 mg + pyridoxine 100 mg IV q6h.'}}],
  admin:'FOMEPIZOLE (preferred, if available): 15 mg/kg IV over 30 min, then 10 mg/kg q12h × 4 doses, then 15 mg/kg q12h. ETHANOL (the usual Indian option): load 0.6–0.8 g/kg IV (6–8 mL/kg of 10% ethanol) over 30–60 min, then maintain 0.1–0.15 g/kg/h (1–1.5 mL/kg/h of 10% ethanol; double the rate in chronic alcoholics) targeting a serum ethanol of 100–150 mg/dL. Oral ethanol (if IV is impossible): 0.8 g/kg of 40% spirit, then 0.15 g/kg/h. ALSO give: folinic acid 1–2 mg/kg IV q4–6h (max 50 mg/dose) for methanol; thiamine 100 mg IV q6h + pyridoxine 100 mg IV q6h for ethylene glycol; sodium bicarbonate for pH <7.3.',
  dil:'Fomepizole dilutes in NS/D5W; ethanol must be given as a diluted solution (≤10%) through a reliable line — extravasation of concentrated ethanol causes tissue necrosis.',
  warn:['HAEMODIALYSIS IS THE DEFINITIVE TREATMENT — start urgently if there is ANY of: pH <7.25–7.30 refractory to bicarbonate, visual symptoms (methanol), renal failure or anuria (ethylene glycol), a methanol level >50 mg/dL (or ethylene glycol >50 mg/dL), a serum osmolal gap >25, or clinical deterioration despite ADH blockade. Continue ADH blockade DURING dialysis (dialysable) and increase the ethanol infusion rate by 50–100%.','Methanol toxicity is caused by FORMIC ACID (visual toxicity: blurred vision, "snowstorm" vision, optic disc hyperaemia then pallor; basal ganglia haemorrhage). Ethylene glycol causes glycolic and oxalic acid (renal failure, calcium oxalate crystals in urine, hypocalcaemia, cranial nerve palsies).','Ethanol causes hypoglycaemia (especially in children and malnourished patients), CNS depression, pancreatitis, hepatitis, phlebitis and intoxication — monitor glucose hourly and the level of consciousness.','Monitor the osmolar gap: (2 × Na) + (glucose/18) + (urea/6) + (ethanol/4.6). A falling gap with a rising anion gap means toxic metabolites are being formed.','Notify public health authorities — methanol outbreaks from illicit liquor are a public-health emergency requiring investigation of the source.','Screen all co-exposed individuals from the same source.','Check calcium, magnesium, phosphate, ABG, lactate, renal function, and fundoscopy every 6–12 h.','Calcium should only be replaced for symptomatic hypocalcaemia in ethylene glycol poisoning (calcium oxalate deposition).'],
  ref:['WHO-TOXIC-ALCOHOL','GOLDFRANK','EXPERT-METHANOL','ICMR-HOOCH','TINTINALLI','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

/* ---------- metals, haem, and other specific antidotes ---------- */
R({ id:'methylene-blue', n:'Methylene blue', sys:'tox', cls:'Redox dye — NADPH-dependent methaemoglobin reductase cofactor',
  ind:'Symptomatic methaemoglobinaemia (MetHb >20–30% with symptoms, or >30% regardless) from dapsone, prilocaine/benzocaine, nitrites, nitroprusside, aniline dyes, naphthalene, well-water nitrate, "poppers"', pop:'all', risk:4,
  d:{t:'mgkg', lo:1, hi:2, cap:100, capDayKg:7, rep:'1–2 mg/kg IV over 5 min (max 100 mg per dose); may repeat after 1 h if MetHb remains >30% (max cumulative 7 mg/kg)'},
  fx:[{s:'10 mg/mL (1%)', c:10, u:'mg', p:'10 mL vial (100 mg), 5 mL ampoule (50 mg)', b:'Methylene Blue IP — Samarth, Neon, Sisco; Methylthioninium chloride', r:'IV', hl:1}],
  admin:'1–2 mg/kg of the 1% solution IV slowly over 5 min (max 100 mg per dose). Recheck MetHb at 1 h; repeat once if still >30% and symptomatic. Effect appears within 30–60 min.',
  dil:'Do not dilute further; inject slowly through a patent IV (extravasation causes necrosis).',
  warn:['CONTRAINDICATED IN G6PD DEFICIENCY (common in parts of India — Parsis, certain tribal and South Indian populations): methylene blue is ineffective (it needs NADPH) AND causes severe haemolysis. Use high-dose ascorbic acid 300–1000 mg IV daily, exchange transfusion or hyperbaric oxygen instead.','SEROTONIN SYNDROME — methylene blue is a potent MAO-A inhibitor. It is contraindicated with SSRIs, SNRIs, TCAs, MAOIs, tramadol, fentanyl, pethidine, bupropion, linezolid, dextromethorphan and triptans.','Doses >7 mg/kg PARADOXICALLY CAUSE methaemoglobinaemia and haemolysis.','Turns urine, skin and sclerae blue-green for 24–48 h (harmless); falsely lowers pulse-oximetry readings — use co-oximetry.','Extravasation → tissue necrosis; intrathecal injection is fatal.','If MetHb does not fall after two doses, suspect a cofactor problem (G6PD, MetHb reductase deficiency), continued exposure, or sulfhaemoglobinaemia.'],
  ref:['GOLDFRANK','TINTINALLI','EXPERT-METHB','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'deferoxamine', n:'Deferoxamine (desferrioxamine)', sys:'tox', cls:'Iron chelator (siderophore)',
  ind:'Acute iron overdose with systemic toxicity (metabolic acidosis, shock, altered mental status, serum iron >500 µg/dL or >350 with symptoms, or >100 mg/kg elemental iron ingested)', pop:'all', risk:4, inf:true,
  d:{t:'mgkghr', lo:15, hi:15, capDay:6000, rep:'15 mg/kg/h IV continuous infusion (max 6 g/day or 80 mg/kg/24 h)'},
  diln:[{l:'2 g in 500 mL NS → 4 mg/mL', amt:2, in:500, u:'g', bag:'500 mL 0.9% NaCl'},
        {l:'500 mg in 50 mL → 10 mg/mL (paediatric)', amt:0.5, in:50, u:'g', bag:'50 mL 0.9% NaCl'}],
  fx:[{s:'500 mg vial', c:50, u:'mg', p:'500 mg vial reconstituted with 5 mL WFI → 95 mg/mL; dilute in NS', b:'Desferal (Novartis), Deferoxamine (limited availability in India — import/named patient)', r:'IV/IM/SC', hl:1, prep:'Reconstitute 500 mg with 5 mL sterile WFI, then dilute in NS to a final concentration ≤4 mg/mL for continuous infusion'}],
  admin:'15 mg/kg/h IV continuous infusion; do NOT exceed 15 mg/kg/h (hypotension) or 6 g/day. Continue until the patient is asymptomatic, the acidosis has resolved, the serum iron is <100 µg/dL and the urine is no longer vin rosé (usually 12–24 h).',
  dil:'Dilute to ≤4 mg/mL for infusion; the reconstituted solution must be used within 24 h.',
  warn:['RAPID IV INFUSION CAUSES PROFOUND HYPOTENSION, FLUSHING AND SHOCK — never bolus, and never exceed 15 mg/kg/h.','The "vin rosé" (reddish-brown) urine is a marker of iron chelation, NOT of haematuria; its absence does not exclude iron toxicity.','ARDS has been reported with prolonged (>24 h) high-dose infusion.','Deferoxamine is only an ADJUNCT — the priority is resuscitation, whole-bowel irrigation (PEG 1–2 L/h via NG until the rectal effluent is clear) for sustained-release or large ingestions, and supportive care. Charcoal does NOT adsorb iron.','Serum iron levels peak at 2–6 h (later for sustained-release); a level drawn too early is falsely reassuring. Repeat at 4–6 h.','Iron levels do not correlate well with outcome — treat the patient, not the number.','Availability in India is erratic — arrange stock in advance for paediatric centres.','Also used for aluminium overload in dialysis patients.'],
  ref:['GOLDFRANK','TINTINALLI','EXPERT-IRON','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'lipid-emulsion', n:'Intravenous lipid emulsion 20% (ILE)', sys:'tox', cls:'Lipid sink / metabolic substrate',
  ind:'LOCAL ANAESTHETIC SYSTEMIC TOXICITY (LAST) — bupivacaine, ropivacaine, lignocaine; and refractory cardiovascular collapse from lipophilic drug overdose (amitriptyline, bupropion, verapamil, diltiazem, propranolol, loperamide, quetiapine, some pesticides)', pop:'all', risk:5, inf:true,
  d:{t:'mlkg', lo:1.5, hi:1.5, capDayKg:12, rep:'bolus 1.5 mL/kg IV over 1 min, then 0.25 mL/kg/min infusion; repeat the bolus once or twice for cardiovascular collapse (max cumulative ≈12 mL/kg)'},
  diln:[{l:'20% lipid emulsion 250 mL bag → 200 mg/mL (ready to use)', amt:200, in:200, u:'mg', bag:'250 mL or 500 mL bag of 20% lipid emulsion'}],
  fx:[{s:'200 mg/mL (20%)', c:200, u:'mg', p:'20 mL ampoule (4 g), 50 mL, 100 mL, 250 mL and 500 mL bags', b:'Intralipid 20% (Fresenius Kabi/Baxter), Lipofundin MCT/LCT 20% (B Braun), Lipovenoes 20%, Emulsion Lipos 20%', r:'IV', hl:1}],
  admin:'LAST protocol (AAGBI/ASRA): (1) STOP the local anaesthetic, call for help, secure the airway and give 100% oxygen; avoid vasopressin, calcium-channel blockers, β-blockers and further local anaesthetics. (2) Standard ACLS with modifications: adrenaline ≤1 mcg/kg (large doses impair lipid resuscitation). (3) ILE 20% 1.5 mL/kg IV over 1 min (≈100 mL in a 70-kg adult), then 0.25 mL/kg/min (≈18 mL/min) for 20 min. (4) Repeat the bolus once or twice for persistent collapse, and increase the infusion to 0.5 mL/kg/min; do not exceed ~12 mL/kg cumulative. (5) Continue the infusion for at least 10 min after circulatory stability, ideally 4–6 h. (6) Treat seizures with benzodiazepines (avoid propofol if the patient is cardiovascularly unstable).',
  dil:'Ready to use — do not mix with other drugs; use a separate line and an in-line filter if available.',
  warn:['ILE INTERFERES WITH MANY LABORATORY ASSAYS (drug levels, electrolytes, coagulation, bilirubin) — draw blood before starting if possible and interpret later results cautiously.','Pancreatitis, fat overload syndrome, ARDS, hepatosplenomegaly and immune modulation with prolonged use.','It is lipid — it will occlude filters and adsorb some drugs; it must NOT be used for nutritional purposes in this context.','Continue standard resuscitation: ILE is an ADJUNCT, not a replacement for ACLS, airway management and vasopressors.','Consider LAST after ANY cardiovascular collapse following a regional block, even if the presentation is delayed (up to 60 min with bupivacaine).','Stock 20% lipid emulsion wherever regional anaesthesia is performed and check the expiry date monthly.','For non-LAST lipophilic drug overdose the same dosing is used, but the evidence is weaker.'],
  ref:['ASRA-LAST','AAGBI-LAST','GOLDFRANK','EXPERT-ILE','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'hydroxocobalamin-cyanide', n:'Hydroxocobalamin / sodium nitrite + sodium thiosulfate — cyanide poisoning', sys:'tox', cls:'Cyanide-binding agent (vitamin B12a) / methaemoglobin-inducing + sulfur-donor antidote',
  ind:'Cyanide poisoning — combustion-product inhalation in house fires, industrial exposure (electroplating, mining, jewellery cleaning), nitroprusside toxicity, cassava/apricot-kernel ingestion, suicide by "detergent suicide" (acid + cyanide salt)', pop:'all', risk:5,
  d:{t:'g', lo:5, hi:10, capDay:10, rep:'hydroxocobalamin 5 g IV over 15 min; repeat 5 g if the response is inadequate (max 10 g)'},
  fx:[{s:'2.5 g/100 mL hydroxocobalamin (Cyanokit)', c:25, u:'mg', p:'2 × 100 mL bottles (5 g total) with a dedicated transfer spike', b:'Cyanokit (Meridian/EBEWE) — VERY LIMITED availability in India; many Indian centres rely on the nitrite–thiosulfate kit', r:'IV', hl:1, prep:'Add 100 mL of the supplied 0.9% NaCl diluent to each 2.5 g bottle using the transfer spike, invert to mix (do not shake), then infuse each bottle over 7.5 min'},
      {s:'Sodium thiosulfate 25% (250 mg/mL)', c:250, u:'mg', p:'20 mL ampoule (5 g), 50 mL vial (12.5 g)', b:'Sodium Thiosulfate IP — Samarth, Neon, Sisco; Hypo (photographic grade is NOT for medical use)', r:'IV', prep:'Give 12.5 g (50 mL of 25%) IV over 10–20 min', own:{a:12500,u:'mg',l:'SODIUM THIOSULFATE 12.5 g IV (50 mL of 25%) over 10–20 min, given IMMEDIATELY AFTER sodium nitrite (child 1.65 mL/kg of 25%, max 50 mL).'}},
      {s:'Sodium nitrite 3% (30 mg/mL)', c:30, u:'mg', p:'10 mL ampoule (300 mg) — availability in India is limited', b:'Sodium Nitrite Injection IP (limited)', r:'IV', own:{a:300,u:'mg',l:'SODIUM NITRITE 300 mg IV (10 mL of 3%) over 5–20 min (child 0.15–0.3 mL/kg of 3%, max 10 mL). CONTRAINDICATED IN SMOKE INHALATION — it adds methaemoglobinaemia to carboxyhaemoglobinaemia. Use hydroxocobalamin instead.'}}],
  admin:'HYDROXOCOBALAMIN (preferred, safe in smoke inhalation): 5 g IV over 15 min; repeat 5 g if needed. NITRITE–THIOSULFATE KIT (if hydroxocobalamin is unavailable and smoke inhalation is excluded): amyl nitrite inhalation while preparing, then sodium nitrite 300 mg (10 mL of 3%) IV over 5–20 min (child 0.15–0.3 mL/kg of 3%, max 10 mL), then IMMEDIATELY sodium thiosulfate 12.5 g (50 mL of 25%) IV over 10–20 min (child 1.65 mL/kg of 25%, max 50 mL). Support with 100% oxygen and treat lactic acidosis.',
  dil:'Hydroxocobalamin must be reconstituted with the supplied diluent only; sodium thiosulfate is used undiluted or diluted in NS.',
  warn:['HYDROXOCOBALAMIN turns the skin, mucosae and urine red-brown for days and INTERFERES WITH COLOUR-BASED LABORATORY ASSAYS (including co-oximetry, creatinine, bilirubin, glucose, magnesium, iron) and with haemodialysis machines — warn the laboratory and document administration in the notes.','SODIUM NITRITE IS DANGEROUS IN SMOKE-INHALATION VICTIMS: it induces methaemoglobinaemia, which compounds carboxyhaemoglobinaemia and can be fatal. In fire victims use hydroxocobalamin or sodium thiosulfate ALONE.','Sodium nitrite causes profound hypotension — infuse slowly with the patient supervised and BP monitoring.','Cyanide toxicity is a CLINICAL diagnosis: sudden collapse, seizures, coma, bright-red venous blood, a narrow venous–arterial oxygen gradient, and severe lactic acidosis (>8 mmol/L) in a smoke-inhalation or industrial-exposure victim. Cyanide levels take days and are not actionable.','Give 100% oxygen, decontaminate (remove clothing, wash skin) and support ventilation.','Sodium thiosulfate is safe, cheap and should be stocked in every Indian ICU where nitroprusside or fire victims are managed — it can be given alone when nitrites are contraindicated.'],
  ref:['GOLDFRANK','TINTINALLI','EXPERT-CYANIDE','FDA-CYANOKIT','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'lcarnitine-valproate', n:'L-carnitine — valproate toxicity', sys:'tox', cls:'Carnitine replacement (restores β-oxidation and urea cycle function)',
  ind:'Valproate-induced hyperammonaemic encephalopathy and hepatotoxicity', pop:'all', risk:3,
  d:{t:'mgkg', lo:50, hi:100, capDay:18000, rep:'acute: 100 mg/kg IV (max 6 g) load, then 15 mg/kg q4h (or 50 mg/kg q6h); chronic: 50–100 mg/kg/day divided'},
  fx:[{s:'200 mg/mL (1 g/5 mL vial)', c:200, u:'mg', p:'5 mL vial (1 g)', b:'L-Carnitine IP — Sun (Elcar), Neon, Intas; Carnitor, Elcar, Carnigen, L-Carn', r:'IV/PO', hl:1},
      {s:'300 mg/mL oral solution', c:300, u:'mg', p:'100 mL bottle', b:'L-Carnitine oral solution, Elcar syrup', r:'PO'},
      {s:'500 mg / 1000 mg tablets', c:1000, u:'mg', p:'strip', b:'L-Carnitine tablets', r:'PO'}],
  admin:'Acute valproate encephalopathy: 100 mg/kg IV over 30 min (max 6 g), then 15 mg/kg IV every 4 h (or 50 mg/kg q6h, max 18 g/day) until the ammonia falls and the patient wakes. Chronic/mild: 50–100 mg/kg/day orally in divided doses.',
  dil:'Dilute in NS or D5W; infuse over 30 min.',
  warn:['STOP VALPROATE IMMEDIATELY and remove all valproate-containing products (including combination antiepileptics).','L-carnitine is most effective for hyperammonaemia and hepatotoxicity; it does not reliably reduce valproate levels.','Consider haemodialysis for very high valproate levels (>900–1300 mg/L), coma, cerebral oedema or refractory acidosis — valproate is dialysable and high-flux dialysis is the definitive treatment.','Fishy body odour, nausea, vomiting, diarrhoea; seizures have been reported at very high doses.','Check ammonia, valproate level, LFTs, glucose, lactate, FBC (thrombocytopenia), pancreatic enzymes and carnitine level.'],
  ref:['GOLDFRANK','EXPERT-VALPROATE','BNF','TINTINALLI','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'digoxin-fab', n:'Digoxin-specific antibody fragments (DigiFab)', sys:'tox', cls:'Passive immunisation — Fab fragments binding digoxin',
  ind:'Life-threatening digoxin/digitoxin toxicity: hyperkalaemia >5.5 mmol/L, life-threatening arrhythmia, cardiac arrest, ingestion >10 mg (adult) or >4 mg (child), or a level >10 ng/mL at 6 h — also effective for oleander (Nerium) and other cardiac-glycoside plant poisoning', pop:'all', risk:5,
  d:{t:'units', lo:1, hi:20, rep:'acute ingestion: number of vials = (ingested mg × 0.8) ÷ 0.5, or vials = (serum digoxin ng/mL × weight kg) ÷ 100; chronic toxicity: 6 vials (adult) or 1 vial (child <20 kg)'},
  fx:[{s:'38 mg vial (binds ≈0.5 mg of digoxin)', c:38, u:'mg', alt:[{u:'units', c:1}], per:'vial', p:'38 mg vial reconstituted with 34 mL WFI → 1 mg/mL', b:'DigiFab (GSK), Digibind — EXTREMELY LIMITED availability in India (import/named-patient; keep a named regional source)', r:'IV', hl:1, prep:'Reconstitute each 38 mg vial with 34 mL sterile WFI, mix gently (do not shake), then further dilute in NS to a total volume of at least 500 mL if needed; if the patient is fluid-restricted, give less diluent'}],
  admin:'CARDIAC ARREST: 10–20 vials (or 20 vials empirically) IV bolus. Life-threatening arrhythmia/hyperkalaemia: calculate the dose and give over 30 min through a 0.22 µm filter. Chronic toxicity in an adult: 6 vials; in a child <20 kg: 1 vial. Recheck K⁺, digoxin level (which becomes UNINTERPRETABLE after Fab) and the ECG.',
  dil:'Reconstitute with WFI; use a 0.22 µm filter if the solution is particulate; compatible with NS and D5W.',
  warn:['AVAILABILITY IN INDIA IS THE LIMITING FACTOR — identify a source before the patient arrives. Supportive care (K⁺ correction, temporary pacing, lidocaine/phenytoin for ventricular arrhythmias, atropine for bradycardia) must continue in parallel.','After Fab administration, total serum digoxin levels are FALSELY ELEVATED and cannot be interpreted for 1–3 days; use the free digoxin assay if available.','HYPOKALAEMIA may develop rapidly as the Na⁺/K⁺-ATPase is reactivated — monitor K⁺ hourly and replace.','Do NOT give IV calcium in digoxin toxicity (theoretical "stone heart" risk); correct hyperkalaemia with insulin–dextrose, bicarbonate, salbutamol, Fab and (if refractory) dialysis (digoxin is NOT dialysable).','Oleander (Nerium oleander) and yellow oleander (Thevetia peruviana) poisoning — common in South India — responds partially to Fab at higher doses (cross-reactivity is incomplete); give 10–20 vials for severe toxicity plus aggressive supportive care.','Anaphylaxis is possible (ovine protein).','Rebound toxicity can occur 1–3 days later as the Fab–digoxin complex dissociates — monitor for at least 3 days.'],
  ref:['GOLDFRANK','EXPERT-DIGOXIN','AHA2025-TOX','BNF','IAP-TOX','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'superwarfarin', n:'Vitamin K1 — rodenticide (superwarfarin) poisoning', sys:'tox', cls:'Fat-soluble vitamin replacement (high-dose, prolonged)',
  ind:'Long-acting anticoagulant rodenticide (brodifacoum, bromadiolone, difenacoum, warfarin) ingestion — increasingly common in India; presents days to weeks later with bleeding and a very high INR', pop:'all', risk:4,
  d:{t:'mg', lo:10, hi:200, capDay:400, rep:'major bleeding: vitamin K1 10 mg IV + 4-factor PCC 25–50 IU/kg (or FFP 15 mL/kg); then 50–200 mg/day PO (or IV) for weeks to months, guided by the INR'},
  fx:[{s:'10 mg/mL', c:10, u:'mg', p:'1 mL ampoule (10 mg)', b:'Vitamin K1 IP — Neon, Samarth, USV; UvK, Vit-K, Kanak', r:'IV/IM/PO', hl:1},
      {s:'10 mg tablet', c:10, u:'mg', p:'strip of 10', b:'Vitamin K tablets (limited availability in India — many centres use the IV ampoule orally)', r:'PO'},
      {s:'4-factor prothrombin complex concentrate (PCC)', c:1, u:'units', p:'500 IU / 1000 IU vials', b:'Confidex, Beriplex, Prothromplex (limited availability in India)', r:'IV', use:'fixed', give:'INR-based dose IV with vitamin K1: INR 2-4 → 25 IU/kg; INR 4-6 → 35 IU/kg; INR >6 → 50 IU/kg (max 5000 IU). Recheck the INR after 30 min.'},
      {s:'Fresh frozen plasma', c:1, u:'ml', p:'200–250 mL unit', b:'Blood bank', r:'IV', use:'fixed', give:'10-15 mL/kg IV if PCC is unavailable - slower, larger volume and less predictable than PCC.'}],
  admin:'ACUTE BLEEDING: vitamin K1 10 mg slow IV + PCC 25–50 IU/kg (or FFP 15 mL/kg if PCC is unavailable). THEN high-dose oral vitamin K1 50–200 mg daily (children 1–5 mg/kg/day) in divided doses with a fatty meal, titrated to keep the INR <1.5. Duration is often 1–6 MONTHS (brodifacoum has a half-life of 20–130 days). Monitor the INR every 1–3 days initially, then weekly.',
  dil:'For IV use, dilute 10 mg in 55 mL of D5W and infuse over 20–30 min (anaphylactoid reactions occur with rapid IV injection). Oral administration of the IV ampoule (mixed in a fatty drink) is a practical option when tablets are unavailable.',
  warn:['The INR may be normal for 24–72 h after ingestion — REPEAT the INR at 24, 48 and 72 h before excluding significant exposure.','Do not discharge after a single normal INR; delayed coagulopathy is the rule.','Prolonged high-dose vitamin K1 is safe but expensive and needs compliance monitoring; the INR will rebound when it is stopped too early.','Activated charcoal within 1–2 h of ingestion; whole-bowel irrigation is not indicated.','Watch for occult bleeding (retroperitoneal, intracranial, GI) — image if there are neurological signs or unexplained anaemia.','Distinguish from warfarin (therapeutic) overdose and from acquired factor inhibitors (mixing studies).'],
  ref:['GOLDFRANK','TINTINALLI','BSH-WARFARIN','IAP-TOX','EXPERT-RODENTICIDE','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'physostigmine', n:'Physostigmine', sys:'tox', cls:'Reversible tertiary amine acetylcholinesterase inhibitor (crosses the blood–brain barrier)',
  ind:'Pure anticholinergic (antimuscarinic) delirium — datura/jimsonweed (very common in India), atropine/scopolamine/hyoscyamine overdose, diphenhydramine, amitriptyline (only with caution), antihistamines; where sedation has failed and the diagnosis is secure', pop:'all', risk:5,
  d:{t:'mgkg', lo:0.02, hi:0.02, cap:2, rep:'adult 1–2 mg IV over 5 min (child 0.02 mg/kg, max 2 mg); may repeat after 10–15 min if there is no response (max 4 mg)'},
  fx:[{s:'1 mg/mL', c:1, u:'mg', p:'1 mL ampoule — availability in India is LIMITED', b:'Physostigmine Salicylate IP (Antilirium) — import/named-patient; many Indian ICUs substitute benzodiazepines', r:'IV/IM', hl:1}],
  admin:'Adult 2 mg IV slowly over at least 5 min (child 0.02 mg/kg over 5 min, max 2 mg) with continuous ECG and atropine 0.5–1 mg drawn up at the bedside. If there is no response, repeat once after 10–15 min. If a response occurs, the effect lasts only 30–60 min — repeat doses may be needed.',
  dil:'Give undiluted slowly, or dilute in 10 mL NS. Do NOT add to dextrose-containing solutions.',
  warn:['ABSOLUTE CONTRAINDICATIONS: a widened QRS (>100 ms) or any evidence of TCA ingestion, asthma/COPD, intestinal or urinary obstruction, peripheral vascular disease, cardiac conduction disease, and concurrent use of depolarising muscle relaxants. Asystole has occurred in TCA overdose.','Cholinergic crisis: bradycardia, AV block, seizures, bronchospasm, salivation, vomiting, diarrhoea, urination — treat with ATROPINE 0.5–2 mg IV (always have it drawn up).','Benzodiazepines plus supportive care are SAFER and are the first-line treatment for anticholinergic agitation; reserve physostigmine for severe, refractory delirium with a secure diagnosis.','Given the availability and safety concerns in India, most centres manage datura poisoning with benzodiazepines, cooling, urinary catheterisation and time.','Datura stramonium poisoning presents with dry flushed skin, mydriasis, hyperthermia, urinary retention, delirium and "picking" behaviour — often after ingestion of seeds added to food/drink (a well-recognised crime in parts of India).'],
  ref:['GOLDFRANK','TINTINALLI','EXPERT-ANTICHOLINERGIC','IAP-TOX','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'salicylate-bicarb', n:'Salicylate poisoning — alkalinisation', sys:'tox', cls:'Urinary alkalinisation (ion trapping)',
  ind:'Aspirin/salicylate overdose with a level >30 mg/dL (2.2 mmol/L), or any symptomatic patient — ion trapping in alkaline urine greatly increases elimination', pop:'all', risk:4, inf:true,
  d:{t:'meqkg', lo:1, hi:2, capDay:400, rep:'1–2 mEq/kg IV bolus, then an infusion of 150 mEq of sodium bicarbonate in 1 L of D5W at 1.5–3 mL/kg/h, keeping urine pH 7.5–8.0'},
  fx:[{s:'8.4% (1 mEq/mL)', c:1, u:'mEq', p:'50 mL vial × 3', b:'Sodabic, Sodium Bicarbonate IP — Samarth, Neon', r:'IV', hl:1},
      {s:'Potassium chloride 15% (2 mmol/mL)', c:2, u:'mmol', p:'15 mL ampoule', b:'KCl 15% IP — Neon, Samarth', r:'IV-additive', use:'fixed', give:'Add 20-40 mmol of KCl to each litre of the alkalinising infusion. Alkalinisation FAILS while the patient is hypokalaemic - the kidney exchanges K+ for H+ and re-acidifies the urine.'},
      {s:'5% dextrose', c:1, u:'ml', p:'1000 mL bag', b:'Dextrose 5% IP', r:'IV', use:'fixed', give:'The diluent for the alkalinising infusion: add 150 mL (3 x 50 mL ampoules) of 8.4% NaHCO3 plus 20-40 mmol KCl to 1 L of D5W and run at 1.5-3 mL/kg/h. Target urine pH 7.5-8.0 and serum pH ≤7.55.'}],
  admin:'(1) Activated charcoal 1 g/kg within 1–2 h (salicylates delay gastric emptying and form concretions — repeat doses are useful). (2) Sodium bicarbonate 1–2 mEq/kg IV bolus, then 150 mEq in 1 L of D5W with 20–40 mmol of KCl at 1.5–3 mL/kg/h; target urine pH 7.5–8.0 and serum pH ≤7.55. (3) Correct hypokalaemia AGGRESSIVELY — alkalinisation fails if K⁺ is low because the kidney reabsorbs K⁺ in exchange for H⁺, acidifying the urine. (4) HAEMODIALYSIS if: salicylate >100 mg/dL (acute) or >60 mg/dL (chronic), altered mental status, cerebral/pulmonary oedema, renal failure, pH <7.20 despite bicarbonate, or clinical deterioration.',
  dil:'Add 150 mL of 8.4% bicarbonate (3 × 50 mL vials) to 1 L of D5W; add 20–40 mmol of KCl.',
  warn:['DO NOT ACIDIFY THE URINE — this drives salicylate into the CNS.','Hypokalaemia must be corrected or alkalinisation will not work.','Avoid intubation if possible: the patient is compensating for a severe metabolic acidosis by hyperventilating, and even a brief period of apnoea during induction can cause a catastrophic fall in pH and cardiac arrest. If intubation is unavoidable, maintain a very high minute volume.','Cerebral and pulmonary oedema are the main causes of death — avoid excessive fluid.','Serial salicylate levels every 2 h (levels continue to rise with sustained-release and enteric-coated preparations and with bezoar formation).','Chronic salicylate toxicity in the elderly presents with confusion and acidosis at much lower levels.','Do not give vitamin K unless the INR is raised (salicylates can cause hypoprothrombinaemia at high levels).'],
  ref:['GOLDFRANK','EXPERT-SALICYLATE','TINTINALLI','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

/* ---------- aluminium phosphide & corrosives (very common in India) ---------- */
R({ id:'aluminium-phosphide', n:'Aluminium phosphide / zinc phosphide (rice-tablet) poisoning', sys:'tox', cls:'Phosphine gas releaser — mitochondrial cytochrome-c oxidase inhibitor',
  ind:'Deliberate self-poisoning with grain preservatives — one of the commonest fatal ingestions in rural Tamil Nadu and across India; NO SPECIFIC ANTIDOTE EXISTS', pop:'all', risk:5,
  d:{t:'text', text:'No antidote. Aggressive supportive care: early gastric decontamination, high-dose magnesium sulfate, vasopressors, mechanical ventilation, ECMO in refractory shock'},
  fx:[{s:'Magnesium sulfate 50% (500 mg/mL)', c:500, u:'mg', p:'2 mL ampoule (1 g), 10 mL vial (5 g)', b:'Magnesium Sulphate IP — Neon, Samarth', r:'IV', hl:1, own:{a:3000,u:'mg',l:'MAGNESIUM SULFATE 3 g IV over 3 h, then 3 g over 6 h, repeated daily for 3 days (total 24 g). Monitor reflexes, respiratory rate ≥16/min and urine output ≥25 mL/h; keep calcium gluconate at the bedside.'}},
      {s:'Potassium permanganate (gastric lavage, 1:10,000)', c:0.1, u:'mg', p:'crystal/tablet dissolved to a pale pink solution', b:'Potassium Permanganate IP (BDH/Merck)', r:'PO-lavage', prep:'Dissolve to make a 1:10,000 solution (pale pink) — it oxidises phosphide to phosphate; NEVER use a dark purple concentration (caustic)', own:{text:'Gastric lavage with 1:10,000 potassium permanganate (a pale pink solution — 1 g in 10 L of water) oxidises phosphide to phosphate. Lavage early, with a protected airway; NEVER induce vomiting (phosphine gas release).'}},
      {s:'Noradrenaline 1 mg/mL', c:1, u:'mg', p:'4 mL ampoule', b:'Norad (Neon), Norex', r:'IV-inf', own:{text:'Noradrenaline 0.05–1 mcg/kg/min IV, titrated to MAP ≥65 mmHg, PLUS dobutamine 5–15 mcg/kg/min for the toxic myocarditis. Avoid large fluid boluses — the myocardium is non-compliant. Consider high-dose insulin–euglycaemia and IABP/ECMO in refractory shock.'}},
      {s:'Coconut oil / vegetable oil (gastric lavage vehicle)', c:1, u:'ml', p:'—', b:'Edible oil — phosphine is lipid-soluble; oil may reduce absorption (weak evidence)', r:'PO', own:{text:'Coconut or vegetable oil via the NG tube reduces phosphine release and absorption (phosphine is lipid-soluble) — give 50–100 mL, then aspirate. Repeat as advised locally.'}}],
  admin:'(1) Decontaminate EARLY: gastric lavage with a 1:10,000 potassium permanganate solution (pale pink) or with coconut/vegetable oil via an NG tube, followed by activated charcoal 1 g/kg and a cathartic. Do NOT induce vomiting (phosphine gas release). (2) MAGNESIUM SULFATE 3 g IV over 3 h, then 3 g over 6 h, repeated daily for 3 days (membrane stabilisation; some evidence of reduced mortality in Indian trials). (3) Aggressive haemodynamic support: fluids (cautious — myocarditis), then noradrenaline; consider high-dose insulin euglycaemia therapy, IABP or VA-ECMO for refractory cardiogenic shock. (4) Monitor the ECG continuously (arrhythmias, QT prolongation), troponin and echocardiography (toxic myocarditis). (5) Ventilatory support for ARDS/metabolic acidosis. (6) Correct severe acidosis (CRRT may be needed for refractory acidosis and AKI). (7) Psychiatric assessment and counselling after recovery.',
  dil:'Potassium permanganate must be pale pink (1:10,000) — concentrated solutions cause corrosive gastric injury.',
  warn:['NO SPECIFIC ANTIDOTE EXISTS — mortality is 40–80% even with optimal care; one tablet (3 g) can be lethal.','Staff safety: phosphine gas is released in the stomach and from vomitus — wear gloves and a mask, work in a well-ventilated area, and avoid inhaling gastric contents (the odour is of decaying fish or garlic).','Refractory hypotension and toxic myocarditis are the main causes of death, usually within 4–24 h.','Avoid excessive fluid (myocardial depression); use vasopressors early.','Do not use oily laxatives repeatedly; do not give milk or fats after the initial decontamination.','Dialysis/haemoperfusion do NOT remove phosphine but may be needed for acidosis and AKI.','Survivors usually recover completely; late sequelae are uncommon.'],
  ref:['IAP-TOX','AIIMS-ALP','ICMR-PESTICIDE','GOLDFRANK','TINTINALLI','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'corrosive-ingestion', n:'Corrosive (acid/alkali) ingestion — supportive care', sys:'tox', cls:'Chemical burn — no neutralising antidote',
  ind:'Ingestion of phenyl/toilet cleaner (hydrochloric or sulfuric acid), drain cleaner (sodium hydroxide), button batteries, "harpic", acid attacks on the self — very common in India', pop:'all', risk:5,
  d:{t:'text', text:'No antidote and NO neutralisation. Airway protection, NPO, IV PPI, analgesia, IV fluids; early CT/endoscopy within 12–24 h to grade the injury'},
  fx:[{s:'Pantoprazole 40 mg vial', c:4, u:'mg', p:'40 mg vial reconstituted in 10 mL NS → 4 mg/mL', b:'Pan (Alkem), Pantocid (Sun), Pantop (Cipla)', r:'IV', hl:1, prep:'Reconstitute 40 mg with 10 mL NS; may be further diluted in 100 mL NS and given over 15 min', own:{a:40,u:'mg',l:'Pantoprazole 40 mg IV twice daily (80 mg IV once, then 8 mg/h, if an ulcer is found at endoscopy).'}},
      {s:'Fentanyl 50 mcg/mL', c:50, u:'mcg', p:'2 mL ampoule', b:'Fentanyl IP — Vamcare, Neon', r:'IV', own:{kgLo:1,kgHi:2,u:'mg',cap:100,l:'Fentanyl 1–2 mcg/kg IV for analgesia (adult 25–100 mcg), titrated. Morphine is an acceptable alternative.'}},
      {s:'Ceftriaxone 1 g vial (if perforation or endoscopic grade ≥2b)', c:100, u:'mg', p:'1 g vial', b:'Rocephin, Monocef', r:'IV', own:{lo:1000,hi:2000,u:'mg',l:'Ceftriaxone 1–2 g IV daily (child 50–100 mg/kg/day) ONLY for perforation, grade 3 injury or documented infection — not routinely.'}},
      {s:'0.9% sodium chloride', c:1, u:'ml', p:'500 mL / 1000 mL bag', b:'Normal Saline IP', r:'IV', own:{text:'Isotonic crystalloid for volume support while the patient is nil by mouth. NOTHING BY MOUTH; do NOT induce vomiting, do NOT give activated charcoal, and do NOT attempt neutralisation with milk, water, antacids or weak acids/alkalis.'}}],
  admin:'(1) Secure the airway early — oropharyngeal/laryngeal oedema progresses over 6–24 h; have a difficult-airway plan and consider awake fiberoptic intubation or a surgical airway. (2) NOTHING BY MOUTH; do NOT induce vomiting, do NOT give activated charcoal, and do NOT attempt neutralisation with milk, water, antacids or weak acids/alkalis (exothermic reactions worsen the injury). (3) IV fluids, IV PPI (pantoprazole 40 mg IV BD), opioid analgesia (fentanyl/morphine), and antiemetics. (4) A nasogastric tube may be placed UNDER DIRECT VISION early to maintain luminal patency and for feeding — but blind insertion is hazardous. (5) CT chest/abdomen with oral contrast (or water-soluble contrast) within 12 h to assess transmural injury, then upper GI endoscopy within 12–24 h (never after 48 h — the wall is at its weakest) to grade the burn (Zargar classification). (6) Grade 0–2a: oral feeding can resume early. Grade 2b–3: NPO, enteral feeding via a nasojejunal tube or parenteral nutrition, consider early surgery for perforation/necrosis. (7) Antibiotics only for perforation, grade 3 injury or infection. (8) Corticosteroids are NOT recommended except possibly in selected grade 2b oesophageal burns within 48 h (controversial — discuss with the surgical/GI team). (9) Long-term: stricture formation in 15–40%; arrange follow-up dilatations and nutritional support.',
  dil:'Standard IV preparations.',
  warn:['NEVER NEUTRALISE AN ACID WITH AN ALKALI OR VICE VERSA — the exothermic reaction deepens the burn.','Activated charcoal is useless and obscures endoscopy.','Emesis and blind NG insertion risk perforation.','Alkali causes liquefactive necrosis (deep, penetrating); acid causes coagulative necrosis (more superficial but with gastric outlet injury). Button batteries cause rapid liquefactive injury from hydroxide generation — remove endoscopically within 2 h if in the oesophagus.','Watch for late complications: tracheo-oesophageal fistula, mediastinitis, aorto-oesophageal fistula, strictures and oesophageal squamous cell carcinoma after 15–40 years.','Document the exact product, concentration and volume ingested — bring the container to the hospital.','Suicide risk assessment and psychiatric care are mandatory.'],
  ref:['GOLDFRANK','TINTINALLI','IAP-TOX','ESGE-CORROSIVE','WSES-CORROSIVE','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

/* ---------- serotonin syndrome / NMS / anticholinergic ---------- */
R({ id:'cyproheptadine', n:'Cyproheptadine — serotonin syndrome', sys:'tox', cls:'First-generation antihistamine with 5-HT2A antagonist activity',
  ind:'Moderate–severe serotonin syndrome refractory to benzodiazepines and supportive care (SSRI/SNRI/MAOI + tramadol, fentanyl, linezolid, dextromethorphan, triptans, MDMA)', pop:'all', risk:3,
  d:{t:'mg', lo:4, hi:12, capDay:32, rep:'adult 12 mg PO, then 2 mg every 2 h while symptoms persist (maintenance 8 mg q6h); child 0.5 mg/kg/day divided'},
  fx:[{s:'4 mg tablet', c:4, u:'mg', p:'strip of 10', b:'Peritol (Abbott), Cypromal, Practin, Cyproheptadine IP — Cipla/Sun', r:'PO', hl:1},
      {s:'2 mg/5 mL syrup', c:0.4, u:'mg', p:'100 mL bottle', b:'Cypon (Samarth), Peritol syrup, Practin syrup', r:'PO'}],
  admin:'(1) STOP all serotonergic agents immediately — this is the most important step. (2) Supportive care: oxygen, IV fluids, external cooling for hyperthermia, and BENZODIAZEPINES (diazepam 5–10 mg IV, repeated) for agitation, tremor and rigidity. (3) Cyproheptadine 12 mg PO/NG, then 2 mg every 2 h until symptoms resolve; maintenance 8 mg q6h. (4) For severe hyperthermia (>41.1 °C) and rigidity: immediate paralysis (non-depolarising NMBA) and intubation — this is life-saving. (5) Avoid physical restraints (rhabdomyolysis) — use chemical sedation.',
  dil:'No parenteral formulation — crush the tablets and give via an NG tube.',
  warn:['Cyproheptadine has NO IV formulation and its benefit is based on case reports/animal data — supportive care and benzodiazepines remain the cornerstone.','DO NOT give dantrolene, bromocriptine or physostigmine in serotonin syndrome (they may worsen it).','Avoid pethidine, tramadol, fentanyl, dextromethorphan, ondansetron, metoclopramide and linezolid — all are serotonergic.','Neuroleptics with 5-HT1A antagonism (chlorpromazine 50–100 mg IM, olanzapine 10 mg SL) are alternatives but carry a hypotension risk.','Monitor for rhabdomyolysis (CK), AKI, DIC and hyperthermia.','Hunter Serotonin Toxicity Criteria: clonus (spontaneous, inducible or ocular) + agitation/diaphoresis/hypertonia + fever in the context of a serotonergic drug.'],
  ref:['GOLDFRANK','EXPERT-SEROTONIN','TINTINALLI','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'bromocriptine-nms', n:'Bromocriptine ± dantrolene — neuroleptic malignant syndrome', sys:'tox', cls:'Dopamine D2 agonist / ryanodine-receptor antagonist',
  ind:'NMS from antipsychotics (haloperidol, olanzapine, risperidone, promethazine) or abrupt withdrawal of dopaminergic drugs in Parkinson disease — rigidity, hyperthermia, autonomic instability, altered mental status, raised CK', pop:'all', risk:4,
  d:{t:'mg', lo:2.5, hi:10, capDay:40, rep:'bromocriptine 2.5–10 mg PO/NG every 6–8 h; dantrolene 0.25–1 mg/kg IV every 6 h (or 1–2 mg/kg IV stat)'},
  fx:[{s:'2.5 mg bromocriptine tablet', c:2.5, u:'mg', p:'strip of 10', b:'Bromocriptine (Abbott India), Parlodel (Novartis), Brome, Bromocriptin', r:'PO', hl:1},
      {s:'20 mg dantrolene vial', c:0.33, u:'mg', p:'20 mg vial reconstituted with 60 mL WFI → 0.33 mg/mL', b:'Dantrolene (Neon/Intas), Dantrium — availability limited in India', r:'IV', prep:'Reconstitute each 20 mg vial with 60 mL sterile WFI (alkaline, pH 9.5); many vials are needed for one adult dose', own:{kgLo:0.25,kgHi:1,u:'mg',l:'DANTROLENE 0.25–1 mg/kg IV every 6 h (or 1–2 mg/kg as a single dose) for severe rigidity and temperature >40 °C. Reconstitute each 20 mg vial with 60 mL sterile water (0.33 mg/mL) and give warm.'}},
      {s:'Diazepam 5 mg/mL', c:5, u:'mg', p:'2 mL ampoule', b:'Diazepam IP — Samarth, Neon', r:'IV/PO', own:{lo:5,hi:10,u:'mg',l:'Diazepam 5–10 mg IV for agitation and to reduce muscle heat production — the first drug to reach for after stopping the antipsychotic.'}}],
  admin:'(1) STOP the offending antipsychotic immediately (this determines the outcome). (2) Aggressive supportive care: external cooling, IV fluids (2–4 L/day) to protect the kidneys from myoglobinuria, correction of electrolytes, benzodiazepines for agitation, and intubation/paralysis for severe hyperthermia or respiratory failure. (3) Bromocriptine 2.5–10 mg PO/NG every 6–8 h. (4) Dantrolene 0.25–1 mg/kg IV every 6 h (or 1–2 mg/kg as a single dose) for severe rigidity and hyperthermia >40 °C. (5) Amantadine 200 mg PO BD or levodopa/carbidopa are alternatives. (6) ECT for refractory cases.',
  dil:'Bromocriptine: crush and give via an NG tube. Dantrolene: reconstitute each vial with 60 mL WFI (labour-intensive).',
  warn:['Mortality is 5–20% — early recognition and stopping the antipsychotic are the decisive interventions.','Monitor CK every 6–12 h, myoglobinuria, renal function, K⁺, calcium, phosphate and coagulation (DIC).','Avoid restarting any antipsychotic for at least 2 weeks; when restarting, use a low-potency atypical agent at a low dose.','Dantrolene is hepatotoxic with prolonged use and its benefit in NMS is based on case reports — supportive care is primary.','Differentiate from serotonin syndrome (hyperreflexia and clonus vs "lead-pipe" rigidity and hyporeflexia), malignant hyperthermia (exposure to volatile anaesthetics/suxamethonium), malignant catatonia, sepsis, anticholinergic toxicity and status epilepticus.','Bromocriptine causes hypotension, nausea and psychosis.'],
  ref:['GOLDFRANK','EXPERT-NMS','BNF','TINTINALLI','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

/* ---------- β-blocker / calcium-channel blocker ---------- */
R({ id:'calcium-ccb-tox', n:'Calcium (gluconate/chloride) — calcium-channel-blocker overdose', sys:'tox', cls:'Calcium salt — overcomes competitive CCB blockade at the L-type channel',
  ind:'Verapamil/diltiazem/amlodipine overdose with hypotension, bradycardia or myocardial depression', pop:'all', risk:4, inf:true,
  d:{t:'mlkg', lo:0.2, hi:0.3, capDay:60, rep:'calcium chloride 10% 0.2–0.3 mL/kg (20–30 mg/kg) IV over 10 min, repeatable; or calcium gluconate 10% 0.6–1 mL/kg (60–100 mg/kg); then an infusion to keep ionised Ca²⁺ 2–2.5 mmol/L'},
  diln:[{l:'10 g calcium gluconate in 100 mL NS → 100 mg/mL (infusion)', amt:10, in:100, u:'g', bag:'100 mL 0.9% NaCl'},
        {l:'10 g calcium chloride in 100 mL NS → 100 mg/mL (CENTRAL LINE)', amt:10, in:100, u:'g', bag:'100 mL 0.9% NaCl'}],
  fx:[{s:'100 mg/mL (10%) calcium gluconate', c:100, u:'mg', p:'10 mL ampoule (1 g) — several ampoules are needed', b:'Calcium Gluconate IP — Neon, Samarth, Saraca', r:'IV', hl:1},
      {s:'100 mg/mL (10%) calcium chloride', c:100, u:'mg', p:'10 mL ampoule (1 g)', b:'Calcium Chloride IP — Neon, Samarth', r:'IV'}],
  admin:'Give calcium chloride 20–30 mg/kg (0.2–0.3 mL/kg of 10%) IV over 10 min via a CENTRAL line, or calcium gluconate 60–100 mg/kg (three times the volume) peripherally. Repeat every 10–20 min as needed, then start an infusion at 0.5–1.5 mL/kg/h of 10% calcium gluconate, titrating the ionised calcium to 2–2.5 mmol/L (or a maximum of 5 mmol/L).',
  dil:'Dilute in NS or D5W; NEVER in bicarbonate-containing or phosphate-containing fluids (precipitation).',
  warn:['Calcium is only PARTIALLY effective — it rarely normalises the blood pressure alone. It must be combined with HIGH-DOSE INSULIN EUGLYCAEMIA THERAPY (the mainstay), IV lipid emulsion, vasopressors (noradrenaline ± adrenaline) and, if available, ECMO or pacing.','Hypercalcaemia causes arrhythmias, vasoconstriction and tissue necrosis on extravasation — use a central line for calcium chloride and monitor ionised calcium hourly.','Do not exceed a total of ~60 mL of 10% calcium gluconate without monitoring.','Calcium is not a substitute for definitive care: prolonged vasodilatory shock from amlodipine may need high-dose insulin for days.','Sustained-release preparations cause delayed and prolonged toxicity — observe for at least 24 h (48 h for SR) even if initially asymptomatic.','Whole-bowel irrigation with PEG is recommended for sustained-release ingestions.'],
  ref:['GOLDFRANK','EXPERT-CCB','TINTINALLI','AHA-TOX','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

/* ---------- other common Indian ICU toxicology ---------- */
R({ id:'antihistamine-sedation', n:'Chlorpheniramine + hydrocortisone — acute allergic reaction / ASV reaction', sys:'tox', cls:'H1-antihistamine + glucocorticoid',
  ind:'Adjunctive treatment of urticaria, pruritus, and early adverse reactions to ASV/antitoxin/blood products (NEVER a substitute for adrenaline in anaphylaxis)', pop:'all', risk:2,
  d:{t:'mgkg', lo:0.1, hi:0.2, cap:10, rep:'chlorpheniramine 10 mg IV (child 0.1–0.2 mg/kg, max 10 mg) + hydrocortisone 200 mg IV (child 2 mg/kg)'},
  fx:[{s:'10 mg/mL chlorpheniramine', c:10, u:'mg', p:'1 mL ampoule (10 mg)', b:'Avil (Sanofi), Chlorpheniramine Maleate IP — Neon/Samarth; Chlorpheniramine', r:'IV/IM/PO', hl:1},
      {s:'4 mg tablet', c:4, u:'mg', p:'strip of 10', b:'Avil 4 mg, Alergin, CPM', r:'PO', own:{a:4,u:'mg',l:'Chlorpheniramine 4 mg PO 6–8 hourly for cutaneous-only reactions (adult). Child: 1 mg per 2 years of age, max 4 mg.'}},
      {s:'100 mg hydrocortisone vial', c:50, u:'mg', p:'reconstitute → 50 mg/mL', b:'Hydrocort (Samarth), Solu-Cortef', r:'IV', own:{lo:100,hi:200,u:'mg',l:'HYDROCORTISONE 200 mg IV in adults (2 mg/kg in children, max 200 mg) — onsets in 4–6 h and never replaces adrenaline.'}},
      {s:'Promethazine 25 mg/mL', c:25, u:'mg', p:'1 mL ampoule — IM ONLY (never IV)', b:'Phenergan (Sanofi), Promethazine IP', r:'IM', own:{lo:12.5,hi:25,u:'mg',l:'Promethazine 12.5–25 mg DEEP IM as an alternative H1 antagonist. CONTRAINDICATED under 2 years of age (fatal apnoea); never give IV (vasospasm and gangrene); give IM only into a large muscle.'}}],
  admin:'For cutaneous-only reactions: chlorpheniramine 10 mg IV slowly (child 0.1–0.2 mg/kg) plus hydrocortisone 200 mg IV (child 2 mg/kg). For ASV/antitoxin reactions: stop the infusion, give IM adrenaline if there are systemic features, then antihistamine + steroid.',
  dil:'Dilute chlorpheniramine in 10 mL NS and give over 1–2 min.',
  warn:['ANTIHISTAMINES AND STEROIDS DO NOT TREAT ANAPHYLAXIS — adrenaline IM is the ONLY first-line drug and must never be delayed.','Sedation from chlorpheniramine can mask neurological assessment in the ICU.','Promethazine must NEVER be given IV — it causes severe tissue necrosis, gangrene and arterial spasm; give deep IM only.','Hydrocortisone has a 4–6 h onset — it does not prevent early biphasic reactions.','Diphenhydramine 25–50 mg IV is an alternative sedating antihistamine.'],
  ref:['AHA2025-ANAPHYLAXIS','NATL-SNAKEBITE-2024','WAO-ANAPHYLAXIS','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });
